mapper.select:
SELECT a.id, a.title, a.content, a.cover_img AS coverImg, a.intcircle_id AS intcircleId, a.create_time AS createTime, a.`like`, IFNULL(COUNT(c.id), 0) AS comment, u.nickname AS hostNickname, u.avatar AS hostAvatar FROM sys_article a JOIN sys_user u ON a.create_user = u.id LEFT JOIN sys_comments c ON a.id = c.article_id
intcircle_id=#{intcircleId}
GROUP BY a.id, a.title, a.content, a.cover_img, a.intcircle_id, a.create_time, a.`like`, u.nickname, u.avatar
